/**
 * #2780 — DRIFT GUARD for in-repo copies of the scaffolded server entries.
 *
 * `apps/*` and `examples/*` hold checked-in copies of the scaffold templates
 * (`knext-bun-entry.mjs`, `knext-node-entry.mjs`). They are found by SCANNING
 * the tree, not from a list, so a new copy is guarded the day it appears.
 *
 * HEADER = the leading block comment opened by a slash-star-star line, if the
 * file starts with one (the template carries a "GENERATED BY" banner; copies
 * may omit or customise it). Everything after it must match the template byte
 * for byte, except allowlisted differences (each needs a reason and must still
 * exist, so a stale entry reds).
 */
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { describe, expect, it } from "vitest";

const ROOT = resolve(__dirname, "../../../..");
const TEMPLATES: Record<string, string> = {
    "knext-bun-entry.mjs":
        "packages/kn-next/templates/app/knext-bun-entry.mjs.hbs",
    "knext-node-entry.mjs":
        "packages/kn-next/templates/app/knext-node-entry.mjs.hbs",
};
// copy path -> reason its body intentionally differs from the template.
const ALLOWLIST: Record<string, string> = {
    "examples/bun-exec/knext-bun-entry.mjs":
        "standalone example: own lockfile, no @getknext/core dependency, so it cannot take the template image-optimizer and sharp imports",
};
// Lines every copy (allowlisted or not) must keep: the taken-port guard.
const GUARD_MARKERS = [
    "import { serve as srvxServe } from 'srvx/bun';",
    "let appListenerReported = false;",
    "process.once('exit', (code) => {",
    "return srvxServe(options);",
    "appListenerReported = true;",
];

function stripHeader(src: string): string {
    const m = /^\/\*\*[\s\S]*?\*\/\n?/.exec(src);
    return m ? src.slice(m[0].length) : src;
}

function findCopies(): string[] {
    const out = execFileSync(
        "git",
        [
            "ls-files",
            "-z",
            "--",
            "*knext-bun-entry.mjs",
            "*knext-node-entry.mjs",
        ],
        { cwd: ROOT, encoding: "utf8" },
    );
    return out.split("\0").filter(Boolean);
}

const read = (p: string) => readFileSync(join(ROOT, p), "utf8");
const copies = findCopies();

describe("in-repo knext entry copies match the scaffold template (#2780)", () => {
    it("finds the known copies by scanning (guard is not vacuous)", () => {
        expect(copies.length).toBeGreaterThanOrEqual(3);
    });

    for (const copy of copies) {
        const tpl = TEMPLATES[copy.split("/").pop() as string];
        it(`${copy} matches ${tpl} outside the header`, () => {
            const want = stripHeader(read(tpl));
            const got = stripHeader(read(copy));
            if (copy in ALLOWLIST) {
                expect(
                    got,
                    `allowlist entry is stale: ${copy} no longer differs`,
                ).not.toBe(want);
            } else {
                expect(got).toBe(want);
            }
        });
    }

    for (const copy of copies) {
        it(`${copy} keeps the taken-port guard`, () => {
            const got = read(copy);
            for (const m of GUARD_MARKERS) expect(got, m).toContain(m);
        });
    }

    it("allowlist entries all name a scanned copy and carry a reason", () => {
        for (const [p, why] of Object.entries(ALLOWLIST)) {
            expect(copies).toContain(p);
            expect(why.length).toBeGreaterThan(0);
        }
    });
});
